With a different babel.config.js I got rid of that plugin not found issue
```
module.exports = function (api) {
    api.cache(true)
    return {
        presets: [
            ["babel-preset-expo", { jsxImportSource: "nativewind" }],
            "nativewind/babel",
        ],
        plugins: [
            "react-native-reanimated/plugin",
        ],
    }
}
```

